from functools import lru_cache
class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        def count(n):
            s = str(n)
            @lru_cache(maxsize=None)
            def dp(i, bal, rem, started, tight):
                if i == len(s):
                    return int(started and bal == 0 and rem == 0)
                res = 0
                limit = int(s[i]) if tight else 9
                for d in range(limit + 1):
                    nt = tight and d == limit
                    if not started and d == 0:
                        res += dp(i + 1, bal, rem, False, nt)
                    else:
                        res += dp(i + 1, bal + (1 if d % 2 == 0 else -1), (rem * 10 + d) % k, True, nt)
                return res
            return dp(0, 0, 0, False, True)
        return count(high) - count(low - 1)

