class Solution {
    string s; int K;
    long long memo[11][23][20][2][2];
    long long dp(int i, int bal, int rem, bool started, bool tight) {
        if (i == (int)s.size()) return (started && bal == 0 && rem == 0) ? 1 : 0;
        auto &m = memo[i][bal + 11][rem][started][tight];
        if (m != -1) return m;
        long long res = 0;
        int lim = tight ? s[i] - '0' : 9;
        for (int d = 0; d <= lim; ++d) {
            bool nt = tight && d == lim;
            if (!started && d == 0) res += dp(i + 1, bal, rem, false, nt);
            else res += dp(i + 1, bal + (d % 2 == 0 ? 1 : -1), (rem * 10 + d) % K, true, nt);
        }
        return m = res;
    }
public:
    long long numberOfBeautifulIntegers(long long low, long long high, int k) {
        K = k;
        auto count = [&](long long n) {
            s = to_string(n);
            memset(memo, -1, sizeof(memo));
            return dp(0, 0, 0, false, true);
        };
        return count(high) - count(low - 1);
    }
};

