class Solution {
    String s; int K;
    Long[][][][][] memo;
    long dp(int i, int bal, int rem, boolean started, boolean tight) {
        if (i == s.length()) return (started && bal == 0 && rem == 0) ? 1 : 0;
        if (memo[i][bal + 11][rem][started ? 1 : 0][tight ? 1 : 0] != null)
            return memo[i][bal + 11][rem][started ? 1 : 0][tight ? 1 : 0];
        long res = 0;
        int lim = tight ? s.charAt(i) - '0' : 9;
        for (int d = 0; d <= lim; d++) {
            boolean nt = tight && d == lim;
            if (!started && d == 0) res += dp(i + 1, bal, rem, false, nt);
            else res += dp(i + 1, bal + (d % 2 == 0 ? 1 : -1), (rem * 10 + d) % K, true, nt);
        }
        return memo[i][bal + 11][rem][started ? 1 : 0][tight ? 1 : 0] = res;
    }
    long count(long n, int k) {
        K = k; s = Long.toString(n);
        memo = new Long[11][23][20][2][2];
        return dp(0, 0, 0, false, true);
    }
    public long numberOfBeautifulIntegers(long low, long high, int k) {
        return count(high, k) - count(low - 1, k);
    }
}

