var numberOfBeautifulIntegers = function(low, high, k) {
    function count(n) {
        const s = String(n);
        const memo = new Map();
        function dp(i, bal, rem, started, tight) {
            if (i === s.length) return started && bal === 0 && rem === 0 ? 1 : 0;
            const key = i + ',' + bal + ',' + rem + ',' + started + ',' + tight;
            if (memo.has(key)) return memo.get(key);
            let res = 0;
            const lim = tight ? +s[i] : 9;
            for (let d = 0; d <= lim; d++) {
                const nt = tight && d === lim;
                if (!started && d === 0) res += dp(i + 1, bal, rem, false, nt);
                else res += dp(i + 1, bal + (d % 2 === 0 ? 1 : -1), (rem * 10 + d) % k, true, nt);
            }
            memo.set(key, res);
            return res;
        }
        return dp(0, 0, 0, false, true);
    }
    return count(high) - count(low - 1);
};
